<template><basic-container><el-card shadow="never">
  <div class="filters"><el-select v-model="query.action" clearable placeholder="全部决策"><el-option v-for="item in actions" :key="item" :label="actionText(item)" :value="item"/></el-select><el-button type="primary" @click="search">查询</el-button></div>
  <el-table :data="page.records" v-loading="loading" stripe><el-table-column prop="eventNo" label="事件编号" width="190"/><el-table-column prop="eventSummary" label="事件摘要" min-width="230" show-overflow-tooltip/><el-table-column prop="recipientName" label="接收人" width="110"/><el-table-column label="AI决策" width="120"><template #default="{row}"><el-tag>{{ actionText(row.decisionAction) }}</el-tag></template></el-table-column><el-table-column prop="decisionReason" label="判断原因" min-width="300" show-overflow-tooltip/><el-table-column prop="confidence" label="置信度" width="90"/><el-table-column prop="oldEvaluateTime" label="原评估时间" width="180"/><el-table-column prop="newEvaluateTime" label="下次评估" width="180"/><el-table-column prop="modelName" label="模型" width="150"/><el-table-column prop="createTime" label="评估时间" width="180"/></el-table>
  <el-pagination class="pager" background layout="total, sizes, prev, pager, next" :total="page.total" v-model:current-page="query.page" v-model:page-size="query.size" @change="load"/>
</el-card></basic-container></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{getAdminEvaluations}from'@/api/smartReminder';const actions=['SEND','DEFER','SKIP','ASK_RECIPIENT','ASK_CREATOR','STOP'],texts={SEND:'发送提醒',DEFER:'延后评估',SKIP:'本次跳过',ASK_RECIPIENT:'询问接收人',ASK_CREATOR:'询问发起人',STOP:'停止分支'};const actionText=v=>texts[v]||v;const loading=ref(false),query=reactive({page:1,size:20,action:''}),page=reactive({records:[],total:0});const load=async()=>{loading.value=true;try{Object.assign(page,(await getAdminEvaluations(query)).data.data||{});}finally{loading.value=false;}};const search=()=>{query.page=1;load();};onMounted(load);</script>
<style scoped>.filters{display:flex;gap:10px;margin-bottom:16px}.filters .el-select{width:180px}.pager{justify-content:flex-end;margin-top:18px}</style>
